import { useState } from "react";
import { useNavigate } from "react-router-dom";
import AdminOverview from "./AdminOverview";
import AdminProducts from "./AdminProducts";
import AdminOrders from "./AdminOrders";
import AdminUsers from "./AdminUsers";
import AdminReviews from "./AdminReviews";

// Sidebar nav items — each has a key that matches what we render below
const NAV_ITEMS = [
  { key: "overview",  icon: "bi-speedometer2", label: "Overview"  },
  { key: "products",  icon: "bi-box-seam",      label: "Products"  },
  { key: "orders",    icon: "bi-bag-check",     label: "Orders"    },
  { key: "users",     icon: "bi-people",        label: "Users"     },
  { key: "reviews",   icon: "bi-star",          label: "Reviews"   },
];

function AdminLayout() {
  const [activeTab, setActiveTab] = useState("overview");
  const navigate = useNavigate();

  // Render the correct admin page based on activeTab
  const renderContent = () => {
    switch (activeTab) {
      case "overview": return <AdminOverview />;
      case "products": return <AdminProducts />;
      case "orders":   return <AdminOrders />;
      case "users":    return <AdminUsers />;
      case "reviews":  return <AdminReviews />;
      default:         return <AdminOverview />;
    }
  };

  return (
    <div className="d-flex" style={{ minHeight: "calc(100vh - 62px)" }}>
      {/* ── Sidebar ── */}
      <aside className="admin-sidebar">
        {/* Brand inside sidebar */}
        <div className="p-3" style={{ borderBottom: "1px solid var(--border)" }}>
          <p className="serif mb-0" style={{ fontStyle: "italic" }}>Admin Panel</p>
          <small className="text-muted">ArtFrame</small>
        </div>

        {/* Nav links */}
        {NAV_ITEMS.map((item) => (
          <button
            key={item.key}
            className={`sidebar-nav-item ${activeTab === item.key ? "active" : ""}`}
            onClick={() => setActiveTab(item.key)}
          >
            <i className={`bi ${item.icon}`}></i>
            {item.label}
          </button>
        ))}


      </aside>

      {/* ── Main Content ── */}
      <main className="admin-content">
        {renderContent()}
      </main>
    </div>
  );
}

export default AdminLayout;
